/**
 * Flag registry resolver (Capitals & Flags design §2).
 *
 * One resolver for every screen: given a flagKey ("fr", "us-ne") it
 * returns the licence-verified curation entry (story line, alt text,
 * attribution) and lazily loads the flag's SVG. Files live in
 * src/assets/flags/ as hashed, per-file chunks via import.meta.glob —
 * nothing is precached (the service worker precaches app chunks, and
 * these load on demand with the pack case that names them), and a land
 * with no verified flag has no entry, so callers render nothing.
 *
 * The metadata module is GENERATED by scripts/packs/build-flags.mjs
 * from the curation record (scripts/packs/capitals/flags/registry.json);
 * never edit it by hand.
 */
import {
  FLAG_ENTRIES,
  type FlagEntry,
} from "@/assets/flags/registry.generated";

export type { FlagEntry };

/**
 * The glob map is built lazily on first use: import.meta.glob exists
 * only under Vite, and importing this module must stay safe in plain
 * node contexts (unit tests import the screens that import this).
 */
let flagLoaders: Record<string, () => Promise<string>> | null = null;
function loaders(): Record<string, () => Promise<string>> {
  if (!flagLoaders) {
    flagLoaders = import.meta.glob<string>("../assets/flags/*.svg", {
      query: "?url",
      import: "default",
    });
  }
  return flagLoaders;
}

/** The curation entry for a flagKey, or null for a flagless land. */
export function flagEntry(flagKey: string | undefined): FlagEntry | null {
  if (!flagKey) return null;
  return FLAG_ENTRIES[flagKey] ?? null;
}

/** Lazily load a flag's asset URL; null when the land is flagless. */
export async function loadFlagUrl(flagKey: string): Promise<string | null> {
  const loader = loaders()[`../assets/flags/${flagKey}.svg`];
  if (!loader) return null;
  return loader();
}

/** Every verified flagKey (gate tests + the curation record). */
export function allFlagKeys(): string[] {
  return Object.keys(FLAG_ENTRIES);
}
